def run(records=8, workers=2, deadline=20):
    \"\"\"Run ready record stages on a fixed number of workers until the deadline.

    Each stage starts after the previous stage for that record finishes. A worker
    stays assigned to a task for its full duration.
    \"\"\"
    remaining = {(r, stage): duration for r in range(records)
                 for stage, duration in STAGES}
    finished, active, events = {}, {}, []
    busy = time = 0

    while (remaining or active) and time < deadline:
        for r in range(records):
            for index, (stage, _) in enumerate(STAGES):
                key = (r, stage)
                if key not in remaining or len(active) >= workers:
                    continue
                if index and (r, STAGES[index - 1][0]) not in finished:
                    continue
                active[key] = remaining.pop(key)
                events.append({"event": "start", "record": r,
                               "stage": stage, "time": time})

        done = []
        for key in list(active):
            active[key] -= 1
            busy += 1
            if active[key] == 0:
                done.append(key)
        time += 1
        for key in done:
            del active[key]
            finished[key] = time
            events.append({"event": "finish", "record": key[0],
                           "stage": key[1], "time": time})

    delivered = sum(finished.get((r, "commit"), deadline + 1) <= deadline
                    for r in range(records))
    return {"records": records, "workers": workers, "deadline": deadline,
            "busy_units": busy, "finished": finished, "events": events,
            "delivered": delivered, "end_time": time,
            "unstarted_or_incomplete": len(remaining) + len(active)}
